function zeroTriples(nums: number[]): number[][] {
  const seen = new Set<string>();
  const out: number[][] = [];
  const n = nums.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      for (let k = j + 1; k < n; k++) {
        if (nums[i] + nums[j] + nums[k] !== 0) continue;
        const t = [nums[i], nums[j], nums[k]].sort((a, b) => a - b);
        const key = t.join(",");
        if (!seen.has(key)) {
          seen.add(key);
          out.push(t);
        }
      }
  return out;
}

