function zeroTriples(nums: number[]): number[][] {
  const a = [...nums].sort((x, y) => x - y); // numeric sort; the default compares as strings
  const out: number[][] = [];
  for (let i = 0; i < a.length - 2; i++) {
    if (a[i] > 0) break; // the rest is positive too
    if (i > 0 && a[i] === a[i - 1]) continue; // same first value, same triples
    let lo = i + 1, hi = a.length - 1;
    while (lo < hi) {
      const sum = a[i] + a[lo] + a[hi];
      if (sum < 0) lo++;
      else if (sum > 0) hi--;
      else {
        out.push([a[i], a[lo], a[hi]]);
        lo++;
        hi--;
        while (lo < hi && a[lo] === a[lo - 1]) lo++;
      }
    }
  }
  return out;
}

